# 思路
基于线段树，待补充


# 复杂度
时间复杂度:  $O(mLogn)$

空间复杂度:  $O(n)$

# Code
```Kotlin
class Solution {
    fun handleQuery(nums1: IntArray, nums2: IntArray, queries: Array<IntArray>): LongArray {
        val tree1=SegmentTree(nums1.size)
        val tree2=SegmentTree(nums2.size)
        val list=ArrayList<Long>()

        tree1.build(nums1)
        tree2.build(nums2)

        for(query in queries){
            when(query[0]) {
                1 -> {
                    tree1.reverse(query[1],query[2])
                }

                2 -> {
                    tree2.plus(0,nums2.size-1,tree1,query[1])
                }

                3 -> {
                    list.add(tree2.select(0, nums2.size - 1))
                }
            }
        }
        return list.toLongArray()
    }
}

class SegmentTree(val n: Int) {
    private val tree: LongArray = LongArray(4 * n) { -1 }
    private val reverseMark = BooleanArray(4 * n) { false }
    private val plusMark = IntArray(4 * n) { 0 }

    fun build(arr: IntArray) {
        build(arr, 0, n - 1, 1)
    }

    private fun build(arr: IntArray, left: Int, right: Int, i: Int) {
        if (left == right) {
            tree[i] = arr[left].toLong()
            return
        }

        val mid = (right - left) / 2 + left

        build(arr, left, mid, 2 * i)
        build(arr, mid + 1, right, 2 * i + 1)

        tree[i] = tree[2 * i] + tree[2 * i + 1]
    }

    fun select(targetLeft: Int, targetRight: Int): Long {
        return select(targetLeft, targetRight, 0, n - 1, 1)
    }

    private fun select(targetLeft: Int, targetRight: Int, left: Int, right: Int, i: Int): Long {
        if (left >= targetLeft && right <= targetRight) {
            return tree[i]
        }
        if (right < targetLeft || left > targetRight) {
            return 0
        }

        val mid = (right - left) / 2 + left
        return select(targetLeft, targetRight, left, mid, 2 * i) + select(
            targetLeft,
            targetRight,
            mid + 1,
            right,
            2 * i + 1
        )
    }

    fun plus(targetLeft: Int, targetRight: Int, tree1: SegmentTree, p: Int) {
        plus(targetLeft, targetRight, 0, n - 1, 1, tree1, p)
    }

    fun plus(
        targetLeft: Int,
        targetRight: Int,
        left: Int,
        right: Int,
        i: Int,
        tree1: SegmentTree,
        p: Int
    ) {
        if (left >= targetLeft && right <= targetRight) {
            tree[i] = tree[i] + tree1.select(left, right) * p
            plusMark[i] += p
            return
        }

        val mid = (right - left) / 2 + left

        if (plusMark[i] > 0 && left != right) {
            tree[2 * i] = tree[2 * i] + tree1.select(left, mid) * plusMark[i]
            tree[2 * i + 1] = tree[2 * i + 1] + tree1.select(mid + 1, right) * plusMark[i]

            plusMark[2 * i] += plusMark[i]
            plusMark[2 * i + 1] += plusMark[i]

            plusMark[i] = 0
        }

        if (targetLeft <= mid) {
            plus(targetLeft, targetRight, left, mid, 2 * i, tree1, p)
        }
        if (targetRight > mid) {
            plus(targetLeft, targetRight, mid + 1, right, 2 * i + 1, tree1, p)
        }

        tree[i] = tree[2 * i] + tree[2 * i + 1]
    }

    fun reverse(targetLeft: Int, targetRight: Int) {
        reverse(targetLeft, targetRight, 0, n - 1, 1)
    }

    fun reverse(
        targetLeft: Int,
        targetRight: Int,
        left: Int,
        right: Int,
        i: Int
    ) {
        if (left >= targetLeft && right <= targetRight) {
            tree[i] = right - left + 1 - tree[i]
            reverseMark[i] = !reverseMark[i]
            return
        }

        val mid = (right - left) / 2 + left

        if (reverseMark[i] && left != right) {
            tree[2 * i] = (mid - left + 1) - tree[2 * i]
            tree[2 * i + 1] = (right - (mid + 1) + 1) - tree[2 * i + 1]

            reverseMark[2 * i] = !reverseMark[2 * i]
            reverseMark[2 * i + 1] = !reverseMark[2 * i + 1]

            reverseMark[i] = false
        }

        if (targetLeft <= mid) {
            reverse(targetLeft, targetRight, left, mid, 2 * i)
        }
        if (targetRight > mid) {
            reverse(targetLeft, targetRight, mid + 1, right, 2 * i + 1)
        }

        tree[i] = tree[2 * i] + tree[2 * i + 1]
    }
}
```

原题地址：https://leetcode.cn/problems/redundant-connection/

## 题解
这道题是一道典型的并查集

我们创建一个dsu的类，包含一个int数组**pa**，其中pa[i]为节点i的父节点，并规定根节点的父节点为自身。

初始状态下，并查集中所有节点都单独为一棵树，pa[i]=i

**查找操作**：

对于任何一个节点x，不断地顺着pa数组向上搜索直到根节点，如果对于两个节点x和y有find(x)==find(y)则说明两个点在同一棵树内

**合并操作**：

由于并查集中的树是多叉树，我们可以直接将x的根节点的父节点重设为y的根节点

对于树而言，树的每一个节点到另一个节点的路径都是**唯一**的，也就是说不存在两个路径使得节点x和节点y都能在同一个连通分量中找到。遍历edges，根据边的两端将两个节点合并，如果某条边的两个节点**已经在同一连通分量**了，则说明这条边为多余边，返回即可

**时间复杂度**：O(NlogN)

**空间复杂度**：O(N)
```Java
class Solution {
    class dsu{
        int[] pa;
        dsu(int size){
            pa=new int[size+1];
            for (int i=0;i<pa.length;i++)pa[i]=i;
        }
        int find(int x){
            //路径压缩，直接将该树的所有节点全设为根节点的第一层子节点，节省查找时间
            return pa[x]==x?x:(pa[x] = find(pa[x]));
        }
        void union(int x,int y){
            pa[find(x)]=find(y);
        }
    }
    public int[] findRedundantConnection(int[][] edges) {
        dsu forest=new dsu(edges.length);
        for (int i=0;i<edges.length;i++){
            if(forest.find(edges[i][0])==forest.find(edges[i][1]))return edges[i];
            forest.union(edges[i][0],edges[i][1]);
        }
        return null;
    }
}
```

原题地址：https://leetcode.cn/problems/robot-bounded-in-circle/

## 题解
基于官方题解思路

不管机器人执行的过程，我们只看机器人在这顿操作中的**始态**和**末态**，本质上机器人每次执行完这一串指令都相当于进行了**一次位移并改变了一次朝向**
- 考虑最简单的情况，如果机器人在执行完指令后仍然在原地，那么理所当然地，机器人永远都走不出原点
- 如果机器人进行了一次位移并改变了朝向，我们可以把这段位移看成一个向量，而朝向则决定了这个向量与上一个向量的夹角
- 当朝向不为北时，说明机器人的每一次**位移向量**都与上一个位移向量形成了一个**夹角**，那么在有限次循环中，机器人必然走出一个**闭合正多边形**的环形路径
- 当朝向为北时，说明机器人的每一次**位移向量**都是上一个向量的延伸，机器人实际上相当于一直在往一个方向移动，也就是唯一一个不会形成环的情况

```java
class Solution {
    public boolean isRobotBounded(String instructions) {
        int x=0,y=0,angle=0;
        for(int i=0;i<instructions.length();i++){
            if(instructions.charAt(i)=='G'){
                if(angle==0)y++;
                else if(angle==180||angle==-180)y--;
                else if(angle==90||angle==-270)x++;
                else if(angle==-90||angle==270)x--;
            }else if(instructions.charAt(i)=='L'){
                angle-=90;
                if(angle%360==0)angle=0;
            }else if(instructions.charAt(i)=='R'){
                angle+=90;
                if(angle%360==0)angle=0;
            }
        }
        if(angle==0&&(x!=0||y!=0))return false;
        else return true;
    }
}
```

原题地址：https://leetcode.cn/problems/count-days-spent-together/

## 题解
通过一个函数`dateToIndex`将**MM-DD**格式的日期转换为**一年中的第N天**，这样我们就能得到Alice和Bob的来往日期在一年中的子区间

如第一个实例中就是：
- Alice:[227,230]
- Bob:[228,231]

对于两个子区间求交集有一套共通的办法：
- 若子区间A的两个边界**均大于B的右边界或均小于B的左边界**，则A和B无交集
- 此外有A和B的交集：**A和B的右边界的较小值减去A和B的左边界的较大值**

$$min(A.right,B.right)-max(A.left,B.left)$$

**时间复杂度**：O(N)

**空间复杂度**：O(1)

```java
class Solution {
    int[] days=new int[]{31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

    public int countDaysTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        int[] alice=new int[2];
        int[] bob=new int[2];
        alice[0]=dateToIndex(arriveAlice);
        alice[1]=dateToIndex(leaveAlice);
        bob[0]=dateToIndex(arriveBob);
        bob[1]=dateToIndex(leaveBob);

        if((alice[0]<bob[0]&&alice[1]<bob[0])||(alice[0]>bob[1]&&alice[1]>bob[1])){
            return 0;
        }else{
            return Math.min(alice[1],bob[1])-Math.max(alice[0],bob[0])+1;
        }
    }

    int dateToIndex(String dateStr){
        int[] date=new int[2];
        date[0]=(dateStr.charAt(0)-'0')*10+(dateStr.charAt(1)-'0');
        date[1]=(dateStr.charAt(3)-'0')*10+(dateStr.charAt(4)-'0');
        int ret=0;
        for(int i=0;i<date[0]-1;i++){ret+=days[i];}
        ret+=date[1];
        return ret;
    }
}
```

原题地址：https://leetcode.cn/problems/time-to-cross-a-bridge/description/

## 题解
定义一个工人由以下几个部分组成：
- index：工人序号
- LtR：从左桥过桥的时间
- up：从右仓库拿起箱子并返回右桥的时间
- RtL：从右桥过桥的时间
- down：从左仓库放下箱子并返回左桥的时间
- time：工人进入仓库的时间（当在桥边等待时无意义）

可以得知
- 当工人进入左仓库操作时，操作完毕的时刻是timer+down
- 当工人进入右仓库操作时，操作完毕的时刻是timer+up

我们维护一个timer计时器记录当前的时刻点

优先队列：
- 对于桥边排队的优先队列，我们每次都取效率最低的，根据题意很容易写出桥边队列的Comparator，即**效率逆序排序**
- 对于仓库中的优先队列，我们考虑每次timer更新时，必定是timer+up/down即完成时刻较小的人从仓库中被移出并加入桥边队列，即**完成时刻升序排序**

当工人过桥时，不论仓库中的工人如何进展，操作完毕后都只能在桥边队列等待，因此在过桥后我们可以直接在timer加上工人过桥的时间

过桥分为四个步骤，以从右桥过桥为例
- 过桥工人=右桥队列中效率最低的工人
- timer计时器+=过桥工人过桥的耗时
- 过桥工人进入左仓库
- 过桥工人的time属性记为当前timer

根据题意定义的优先级：
- 当右桥队列有人时，令效率最低的人过桥
    - 当右桥队列此时为空，且右仓库的箱子数量为空时，则说明当前工人已为最后一个工人，返回过桥后timer
- 当左桥队列有人**且右仓库中工人数量小于右仓库中箱子数量**时，令效率最低的人过桥
- 当两边队列均无人（可能所有工人都在仓库中操作），timer++空闲等待

```kotlin
class Solution {
    fun findCrossingTime(n: Int, k: Int, time: Array<IntArray>): Int {
        /*
            工人数组定义
            |0      |1      |2      |3      |4      |5
            |index  |LtR    |up     |RtL    |down   |time（进入仓库的时间，完成作业时间即timer+up/down）
         */
        val efficiency = Comparator<IntArray> { a, b ->
            if (a[1] + a[3] != b[1] + b[3]) {
                (b[1] + b[3]) - (a[1] + a[3])
            } else {
                b[0] - a[0]
            }
        }
        val pickUp = Comparator<IntArray> { a, b -> (a[5] + a[2]) - (b[5] + b[2]) }
        val pickDown = Comparator<IntArray> { a, b -> (a[5] + a[4]) - (b[5] + b[4]) }

        val leftWorkers = PriorityQueue(efficiency)     //左桥排队
        val rightWorkers = PriorityQueue(efficiency)    //右桥排队
        val leftRepo = PriorityQueue(pickDown)          //左仓库操作中工人
        val rightRepo = PriorityQueue(pickUp)           //右仓库操作中工人

        var leftCnt = 0     //左仓库箱子数量
        var rightCnt = n    //右仓库箱子数量
        var timer = 0       //计时器

        var worker: IntArray
        for ((index, arr) in time.withIndex()) {
            leftWorkers.add(intArrayOf(index) + arr + intArrayOf(0))
        }

        while (leftCnt < n) {
            //由于计时器更新，刷新仓库中工人状态，操作完毕的工人回到桥上等待
            while (leftRepo.size > 0 && leftRepo.first()[5] + leftRepo.first()[4] <= timer) {
                leftWorkers.add(leftRepo.remove())
                leftCnt++
            }
            while (rightRepo.size > 0 && rightRepo.first()[5] + rightRepo.first()[2] <= timer) {
                rightWorkers.add(rightRepo.remove())
                rightCnt--
            }
            if (rightWorkers.size > 0) {
                //右桥工人过桥，并进入左仓库
                worker = rightWorkers.remove()
                timer += worker[3]
                worker[5] = timer
                leftRepo.add(worker)

                //当前工人已为最后一个工人
                if (rightWorkers.size == 0 && rightCnt == 0) {
                    return timer
                }
            }else if(leftWorkers.size > 0 && rightRepo.size < rightCnt) {
                //左桥工人过桥，并进入右仓库
                worker = leftWorkers.remove()
                timer += worker[1]
                worker[5] = timer
                rightRepo.add(worker)
            }else {
                //空闲等待，桥边无人等待
                timer++
            }
        }
        return 0
    }
}
```

> Problem: [57. 插入区间](https://leetcode.cn/problems/insert-interval/description/)

# 思路
由于题干指明了**原区间序列是有序且无重叠的**，可以为我们省去许多功夫

我们用一个min和一个max记录当前合并区间的左边界和右边界，且初始化为`newInterval`的左边界和右边界

顺序遍历`intervals`，可以对遍历到的`interval`分为两种情况：
- 当`interval`和**当前的合并区间**无重叠部分时，可以直接将`interval`添加至结果`res`中
- 当`interval`和**当前的合并区间**有重叠部分时，即`interval`可以和当前的合并区间再次合并，**新的合并区间**中左边界`min`应当取`interval[0]`和`min`中较小的一个，右边界`max`应当取`interval[1]`和`max`中较大的一个

由于`intervals`本身是有序的，当`interval`不再满足该条件时，即可将合并区间`[min,max]`插入`res`中

# 复杂度
- 时间复杂度:  $O(n)$

- 空间复杂度:  $O(n)$，主要是存储返回结果用的ArrayList，如果不考虑这个也可以认为是$O(1)$

# Code
```Kotlin
class Solution 
fun Solution.insert(intervals: Array<IntArray>, newInterval: IntArray): Array<IntArray> {
    if (intervals.size == 0) return arrayOf(newInterval)

    val res = ArrayList<IntArray>()
    var min = newInterval[0]
    var max = newInterval[1]
    var flag = false
    var done = false

    for (interval in intervals) {
        if ((interval[0] <= min && interval[1] >= min)
            || (interval[0] <= max && interval[1] >= max)
            || (interval[0] >= min && interval[1] <= max)
        ) {
            min = Math.min(min, interval[0])
            max = Math.max(max, interval[1])
            flag = true
        } else if (flag) {
            res.add(intArrayOf(min, max))
            res.add(interval)
            flag = false
            done = true
        } else {
            res.add(interval)
        }
    }
    if (!done) {
        res.add(intArrayOf(min, max))
    }

    return res.sortedBy { it[0] }.toTypedArray()
}
```

> Problem: [833. 字符串中的查找与替换](https://leetcode.cn/problems/find-and-replace-in-string/description/)

# 思路
这道题需要考虑到的细节主要有两点：
- target中被替换的字符串的长度会与原子字符串不同，从而导致原字符串对应的下标发生变化，例如`abc`将`a`替换为`aaa`，则`b`的下标会从1变为3
- 由于替换是**同时进行**的，我们不能在被替换的字符串中寻找子字符串（由于题干保证了每组操作不会包含重叠的字符串，所以这点不需要考虑了）

对操作的索引`indices`进行排序，可以同时解决上面两个问题
- 当我们先对索引较小的子字符串进行替换操作时，即便仍然会影响下标的对应关系，但此时影响的是该子字符串后面的**所有字符**的对应关系，我们简单地可以用一个偏移值变量`shift`维护这个偏移关系，即每次令`shift+=targets[i].length-sources[i].length`
- 由于我们按索引升序进行替换操作，可以保证，在第i次操作后，`indices[i]+shift+source[i].length`（即被替换完的子字符串末尾处索引）左侧均已完成替换操作，接下来的操作中我们只需要在该索引右侧查找即可，避免了从被替换的字符串中寻找子字符串的情况（由于题干保证了每组操作不会包含重叠的字符串，所以这点不需要考虑了）


从str的`indices[i]+shift`索引处通过`indexOf`查找`source[i]`，如果结果等于`indices[i]+shift`则说明索引处存在该子字符串，直接进行替换操作即可

# 复杂度
- 时间复杂度: 快速排序平均时间复杂度为 $O(NlogN)$，字符串替换操作时间复杂度为$O(N)$

- 空间复杂度: 快速排序需要的空间复杂度为$O(logN)$，字符串替换操作空间复杂度为$O(N)$

# Code
```Kotlin 

class Solution {
    fun findReplaceString(s: String, indices: IntArray, sources: Array<String>, targets: Array<String>): String {
        quickSort(indices, sources, targets, 0, indices.size - 1)
        var shift = 0
        var str = s
        for (i in indices.indices) {
            if (str.indexOf(sources[i], indices[i] + shift) != indices[i] + shift) {
                continue
            }
            str = str.substring(0, indices[i] + shift) + targets[i] + str.substring(indices[i] + shift + sources[i].length)
            shift += targets[i].length - sources[i].length
        }
        return str
    }

    fun quickSort(indices: IntArray, sources: Array<String>, targets: Array<String>, beginIndex: Int, endIndex: Int) {
        if (beginIndex >= endIndex) return
        val mid = indices[beginIndex]
        var left = beginIndex
        var right = endIndex
        while (left < right) {
            while (indices[right] > mid && left < right) {
                right--
            }
            if (left < right) swap(indices, sources, targets, left++, right)
            while (indices[left] < mid && left < right) {
                left++
            }
            if (left < right) swap(indices, sources, targets, left, right--)
        }

        quickSort(indices, sources, targets, beginIndex, left - 1)
        quickSort(indices, sources, targets, left + 1, endIndex)
    }


    fun swap(indices: IntArray, sources: Array<String>, targets: Array<String>, a: Int, b: Int) {
        swap(indices, a, b)
        swap(sources, a, b)
        swap(targets, a, b)
    }

    fun swap(arr: IntArray, a: Int, b: Int) {
        val tmp = arr[a]
        arr[a] = arr[b]
        arr[b] = tmp
    }

    fun swap(arr: Array<String>, a: Int, b: Int) {
        val tmp = arr[a]
        arr[a] = arr[b]
        arr[b] = tmp
    }
}
```

原题地址：https://leetcode.cn/problems/longest-substring-with-at-most-two-distinct-characters/

## 题解
### 滑动窗口
设left和right分别为窗口的两端指针，且窗口内元素永远为符合条件的元素

**基本思路**：

维护一个map，记录窗口中每个字符的数量，right不断向右扩展，并维护map，当map[s.charAt(right)]自加完等于1，则说明此字符是一个**新字符**，用flag记录下当前窗口内字符种类数，当下一个字符的map为0且flag为2时则跳出循环，此时[left,right]为固定当前left指针下的最长窗口

此时更新left使窗口收缩，每次map[s.charAt(left)]--然后left++来删除最左端字符，当删除到某个字符的map为0时说明成功删除窗口中的一种字符，由于此时的right指针已经在map自加过一次，更新完left后需要让right再++一次来跳过

**时间复杂度**：O(N)

**空间复杂度**：O(1)

```java
class Solution {
    public int lengthOfLongestSubstringTwoDistinct(String s) {
        int left=0,right=0,max=Integer.MIN_VALUE;
        int[] map=new int[128];
        int flag=0;
        while (left<s.length()){
            while (right<s.length()){
                map[s.charAt(right)]++;
                //当前字符为新字符则flag++
                if(map[s.charAt(right)]==1){
                    if(flag<2)flag++;
                }
                //下一个字符为新字符则跳出
                if(right==s.length()-1||(flag==2&&map[s.charAt(right+1)]==0)){
                    break;
                }
                right++;
            }
            max=Math.max(max,right-left+1);
            while (left<right){
                map[s.charAt(left)]--;
                left++;
                //减少一种字符则跳出
                if(map[s.charAt(left-1)]==0)break;
            }
            right++;
        }
        return max;
    }
}
```

# 209.长度最小的子数组 - Java 滑动窗口
原题链接：https://leetcode.cn/problems/minimum-size-subarray-sum/

## 题解
维护一个**滑动窗口**，并维持以下原则：
- right一直向右扩展至sum>=target
- left一直向右伸缩至sum<target

由于right扩展后的子数组不一定是最优解，在left伸缩后可能仍然有sum>=target，right固定时的最优解应为：**当前right不变，left伸缩到满足sum>=target的最右边时的长度**

所以我们每次在left伸缩时再根据sum是否大于等于target更新min

**时间复杂度**：O(N)；
**空间复杂度**：O(1)；

```java
class Solution {
    public int minSubArrayLen(int target, int[] nums) {
        int sum=nums[0],min=999999;
        int left=0,right=0;

        while(right<nums.length-1){
            while(sum<target&&right+1<nums.length){
                right++;
                sum+=nums[right];
            }
            while(sum>=target&&left<nums.length){
                if(min>right-left+1)min=right-left+1;
                sum-=nums[left];
                left++;
            }
        }
        if(min==999999)return 0;
        return min;

    }
}
```

原题地址：https://leetcode.cn/problems/longest-substring-without-repeating-characters/

## 题解
滑动窗口，初始化left和right指针为0

一开始将窗口扩展，right++一直到s.charAt(right+1)为重复元素，此时[left,right]为当前left下的最大窗口

将窗口收缩，left++一直到s.charAt(right+1)不再为重复元素，此时阻碍消失，right继续++至s.charAt(right+1)为重复元素

将每次扩展完后的窗口长度取最大值即为最长的子字符串

**时间复杂度**：O(N)

**空间复杂度**：O(1)
```java
class Solution {
    public int lengthOfLongestSubstring(String s) {
        if(s.length()==0)return 0;

        int left=0,right=0,max=Integer.MIN_VALUE;
        Set<Character> set=new HashSet<>();
        set.add(s.charAt(0));

        while (left<s.length()){
            //扩展窗口
            while (right<s.length()-1&&!set.contains(s.charAt(right+1))){
                right++;
                set.add(s.charAt(right));
            }
            max=Math.max(max,right-left+1);

            //当扩展完毕后right为数组末尾，则接下来窗口值只能缩减，不存在更大的解，跳出循环
            if(right==s.length()-1)break;

            //收缩窗口
            while (left<s.length()&&s.charAt(left)!=s.charAt(right+1)){
                set.remove(s.charAt(left));
                left++;
            }
            set.remove(s.charAt(left));
            left++;
        }
        return max;
    }
}


```

原题地址：https://leetcode.cn/problems/check-if-word-is-valid-after-substitutions/

## 题解
当我们插入i次abc时，由于没有后续插入，第i次插入的abc一定在s中的某个位置以连续的“abc”形式存在，当我们删除这个连续的“abc”时，实际上相当于将s还原到了第i-1次插入的情况

如果s是有效的，则我们可以不断迭代到第0次插入，即将s还原回空字符串的情况。如果还原到最后无法使s变为空字符串，则说明该字符串无效

我们可以用一个数组模拟栈，用i遍历s，每次将i插入数组末尾，如果数组末尾的三个字符满足一个连续的“abc”，则我们将其删除，如果遍历完毕后数组为空（需要用一个top指针来维护数组长度），则说明s有效

**时间复杂度**：O(N)

**空间复杂度**：O(N)

```java
class Solution {
    static char[] stack=new char[20001];
    public boolean isValid(String s) {
        if(s.length()%3!=0)return false;
        char[] sarr=s.toCharArray();
        int top=-1;//top -1则说明当前栈为空
        for (int i=0;i<sarr.length;i++){
            if(sarr[i]=='c'&&top+1>=2&&stack[top]=='b'&&stack[top-1]=='a'){
                top-=2;//满足连续的abc则将栈顶的a和b出栈
            }else{
                stack[++top]=sarr[i];//不满足则入栈
            }
        }
        return top==-1;//返回栈是否为空
    }
}
```

原题地址：https://leetcode.cn/problems/distant-barcodes/

## 题解
这题其实是一道简化版的[任务调度器](https://leetcode.cn/problems/task-scheduler/)，对于题目中要求的“相邻数字不能重复”，我们可以立即为“不能连续填入两个相同数字”，对比到**任务调度器**这道题，实际上就是相当于说**每个任务的冷却时间为1**，由于CD只有1，这道题我们可以直接通过**滚动数组**来实现冷却

自然地，对于**能用的未在冷却的数字**，我们希望尽可能优先去用**出现次数较多**的数字，这样才能避免出现次数少的数字提前被用完而不得不使剩下的数字重复填入。在记录下每个数字的出现次数后，我们创建一个优先队列，按照**出现次数的降序**进行排列

设coolDown[0]为当前已冷却完的数字，coolDown[1]为当前进入冷却的数字

每次从优先队列取出数字时，先**经过一个单位时间**，将coolDown[0]设为coolDown[1]，而coolDown[1]为取出的数字，即**上一个数字已经冷却完毕，当前数字开始进入冷却状态**，取出数字后，将对应数字按顺序插入数组即可

更新完毕后，由于coolDown[0]已经冷却完毕，判断coolDown[0]的数字是否仍有剩余次数，若有则重新加入优先队列

**时间复杂度**：O(N)

**空间复杂度**：O(N)

```java
class Solution {
    public int[] rearrangeBarcodes(int[] barcodes) {
        int[] amount=new int[10001];
        int[] ret=new int[barcodes.length];
        int itr=0;
        for (int i:barcodes){
            amount[i]++;
        }
        PriorityQueue<Integer> que=new PriorityQueue<>((Integer a,Integer b)->{return amount[b]-amount[a];});
        for (int i=1;i<=10000;i++){
            if(amount[i]!=0)que.add(i);
        }

        int[] coolDown=new int[2];
        while (!que.isEmpty()){            
            coolDown[0]=coolDown[1];
            coolDown[1]=que.remove();
            if(coolDown[0]!=0&&amount[coolDown[0]]!=0){
                que.add(coolDown[0]);
            }
            amount[coolDown[1]]--;
            ret[itr++]=coolDown[1];
        }
        return ret;
    }
}
```

原题地址：https://leetcode.cn/problems/non-overlapping-intervals/

## 题解
参考题解思路

我们将最终版本的区间集合视作**一个List或Queue**，而我们的目标是：**不断地向List中插入符合条件的区间**

对于一个空List，我们思考如何往里添加第一个元素，我们并**不在意这个区间的左边界**，而是这个区间的**右边界**，为了向List里加入尽可能多的元素，考虑到List[i]的左区间必然小于List[i-1]的右区间，我们选择一个**右边界尽可能小的区间**，这样能为后续的插入**预留出更多的空间**

我们对intervals按照**区间的右边界**升序排序

当往里插入了一些区间后，我们只需要按顺序遍历intervals，由于intervals已经按照右边界升序排序，只要遍历到一个满足**左边界小于List中最后一个区间的右边界（用一个start维护）**的区间，这个区间必然是满足条件的所有区间的最优解，直接将其插入List，然后维护start变量即可

最后对于List的size就是无重叠区间的最大数量，用intervals.size减去这个值就是我们需要的答案

**时间复杂度**：O(N)

**空间复杂度**：O(1)
```Java 
class Solution {
    public int eraseOverlapIntervals(int[][] intervals) {
        Arrays.sort(intervals, Comparator.comparingInt((int[] a) -> a[1]));
        int start=Integer.MIN_VALUE;
        int cnt=0;
        for (int i=0;i<intervals.length;i++){
            if(intervals[i][0]>=start){
                start=intervals[i][1];
                cnt++;
            }
        }
        return intervals.length-cnt;
    }
}
```
```Kotlin 
class Solution {
    fun eraseOverlapIntervals(intervals: Array<IntArray>): Int {
        intervals.sortBy{ it[1] }
        var start=Int.MIN_VALUE
        var cnt=0
        for(i in 0 until intervals.size){
            if(intervals[i][0]>=start){
                start=intervals[i][1]
                cnt++
            }
        }
        return intervals.size-cnt
    }
}
```

